UPDATE companies SET description='Mission Foods operates as a subsidiary of Gruma Corporation, a tortilla manufacturer founded in 1949 that now leads the global market. While Gruma''s roots trace back to Mexico, Mission Foods serves as the company''s primary U.S. brand, with corporate headquarters in Irving, Texas, and a significant facility in Colorado Springs, Colorado.

The company manufactures a broad line of Mexican-style foods, including flour and corn tortillas, wraps, flatbreads such as naan and pita, tortilla chips (offered in organic, protein, and grain-free varieties), chicharrones, and salsa. Product development has expanded into better-for-you categories: low-carb, high-fiber, high-protein, organic, and gluten-free formulations.

The brand also engages home cooks directly through a large recipe library organized around meal occasions—quick meals, party dishes, vegetarian, air-fryer preparations, and holiday collections.

Mission Foods frames its purpose around exploration and shared meals: "Great food is a great motivator. It brings everyone to the table and inspires us to explore all kinds of delicious destinations." The company says it seeks the freshest ingredients and simple recipes to create wholesome products that enable better-for-you eating without abandoning traditional favorites like tacos and nachos.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Flour tortilla manufacturing", "Corn tortilla manufacturing", "Wrap and flatbread production", "Tortilla chip manufacturing", "Salsa production", "Chicharrones production"], "industries": ["Food manufacturing", "Mexican food products", "Consumer packaged goods", "Retail grocery", "Foodservice"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Subsidiary of Gruma Corporation, the leading global tortilla manufacturer", "Extensive better-for-you portfolio: high-protein, low-carb, gluten-free, organic, and grain-free lines", "Title sponsor of the NHRA Premier Professional Series", "Direct-to-consumer recipe platform with meal-occasion collections"], "facts_used": ["Gruma Corporation founded 1949 -> /about-us", "Mission Foods subsidiary of Gruma -> /about-us", "Mission Foods #1 tortilla company in U.S. -> /about-us", "Manufactures wide variety of authentic Mexican products -> /about-us", "Corporate headquarters in Irving, Texas -> /about-us", "Facility in Colorado Springs, Colorado -> db", "Product lines: flour tortillas, corn tortillas, wraps, flatbreads, chips, chicharrones, salsa -> /", "Better-for-you lines: low-carb, high-fiber, high-protein, organic, gluten-free, grain-free -> /", "Retail and foodservice distribution -> /", "Recipe library for home cooks -> /", "NHRA title sponsorship -> /about-us", "Purpose statement: great food motivator, freshest ingredients, simple recipes -> /about-us"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "manufactures a wide variety of authentic Mexican products", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='mission-foods' AND approved AND profile IS NULL;
UPDATE companies SET description='Mission Plastics, headquartered in Grandview, Missouri, has specialized in custom injection molding since 1968. The company is family-owned and operated and operates as part of the Peterson Manufacturing family of businesses, which provides additional vertically integrated capabilities such as metal stamping, PCB manufacturing, and wire harness assembly.

Mission Plastics runs two facilities—in Greater Kansas City and Southwest Arkansas—totaling 198,000 square feet, including a 50,000-square-foot on-site tool shop. Its 96 injection molding machines range from 35 to 610 tons, with five vertical and three two-shot presses. The shop offers insert molding, overmolding, automation, mold design, engineering, prototyping, and turnkey manufacturing, all under ISO 9001:2015 and UL certification.

The molder serves consumer products, industrial applications, lawn and garden, and lenses and optics. Long-term customers include Milbank (cited by buyer Sarah Brown), a global manufacturer (referenced by its director of design and engineering), and a Fortune 500 company (noted by engineering manager Michael Ranta).

Mission Plastics emphasizes its family-owned culture, with many master crafters exceeding 20 years of tenure, and its financially stable, debt-free structure. Sustainability initiatives include returnable packaging systems, scrap reduction, and recycling programs aimed at reducing landfill waste.', certifications=ARRAY['ISO 9001:2015','UL-certified molder']::text[], profile='{"capabilities": ["Custom Injection Molding", "Insert Molding", "Overmolding", "Two-Shot Molding", "Vertical Molding", "Automation", "Mold Design & Tooling", "Engineering", "Prototyping", "Turnkey Manufacturing", "Design & Engineering Services", "Auditing", "Inventory Management", "Warehousing", "UV Coating/Painting", "Metal Stamping", "PCB Manufacturing", "Wire and Harness Manufacturing", "Lens and Optic Design", "Lens and Optic Manufacturing", "Lens and Optic Testing", "Automation Design"], "industries": ["Consumer Products", "Industrial Applications", "Lawn & Garden", "Lenses and Optics"], "materials": [], "equipment": ["96 injection molding machines (35\u2013610 ton)", "5 vertical molding machines", "3 two-shot molding machines", "50,000-square-foot on-site tool shop", "High-tech inspection cameras"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Family-owned with master crafters averaging 20+ years tenure", "Vertically integrated with Peterson Manufacturing for in-house design, tooling, and molding", "ISO 9001:2015 and UL-certified molder", "Two facilities totaling 198,000 sq ft with 96 injection molding machines (35\u2013610 ton)", "Sustainability programs including returnable packaging and scrap reduction"], "facts_used": ["Founded 1968 -> /about-us", "Family-owned and operated -> /about-us", "Two facilities in Greater Kansas City and Southwest Arkansas -> /about-us", "96 injection molding machines (35-610 ton), 5 vertical, 3 two-shot -> /about-us", "198,000 total square feet, 50,000 sq ft tool shop -> /about-us", "ISO 9001:2015 certified, UL-certified molder -> /about-us